Definition cfg_eqv (c1 c2 : config) : Prop := ms_eqv (cfg_ms c1) (cfg_ms c2) /\ cfg_model c1 = cfg_model c2.

Definition st_eqv (s1 s2 : step_to) : Prop :=
  match s1, s2 with
  | SNext c1, SNext c2 => cfg_eqv c1 c2
  | SError, SError => True
  | _, _ => False
  end.

Lemma sstep_eqv : forall c1 c2 evs st2, cfg_eqv c1 c2 -> sstep segs c2 evs st2 ->
  exists st1, sstep segs c1 evs st1 /\ st_eqv st1 st2.
Proof.
